import{_ as s,o as i,c as t,a2 as a}from"./chunks/framework.oPQd_6mD.js";const h=JSON.parse('{"title":"Déployer VitePress sur GitHub Pages","description":"","frontmatter":{},"headers":[],"relativePath":"maintenance/pages-github.md","filePath":"maintenance/pages-github.md","lastUpdated":null}'),n={name:"maintenance/pages-github.md"};function o(r,e,l,p,c,d){return i(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="deployer-vitepress-sur-github-pages" tabindex="-1">Déployer VitePress sur GitHub Pages <a class="header-anchor" href="#deployer-vitepress-sur-github-pages" aria-label="Permalink to &quot;Déployer VitePress sur GitHub Pages&quot;">​</a></h1><p>La documentation publique est séparée des sources du plugin. Le dépôt GitHub <code>vevedh/vite-plugin-feathersjs</code> possède actuellement un historique différent de la branche de laboratoire : <strong>ne copiez pas toute l’archive R17 dans <code>main</code></strong>. Seuls les fichiers <code>docs/cli</code> et le workflow <code>.github/workflows/cli-vitepress-pages.yml</code> sont destinés à ce dépôt.</p><h2 id="_1-verifier-la-documentation-sur-windows" tabindex="-1">1. Vérifier la documentation sur Windows <a class="header-anchor" href="#_1-verifier-la-documentation-sur-windows" aria-label="Permalink to &quot;1. Vérifier la documentation sur Windows&quot;">​</a></h2><p>Dans une session PowerShell avec Git et Node.js installés :</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Set-Location</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> C:\\devs\\vite</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">plugin</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">feathersjs</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\scripts\\r17\\certify</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">and</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">stage</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pages</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">windows.ps1</span></span></code></pre></div><p>Cette commande contrôle le gel du projet, les pages, le périmètre de publication, puis construit le site avec le préfixe <code>/vite-plugin-feathersjs/</code>. Elle prépare une branche <strong>sans la pousser</strong> pour permettre une relecture.</p><h2 id="_2-publier-les-sources-de-documentation" tabindex="-1">2. Publier les sources de documentation <a class="header-anchor" href="#_2-publier-les-sources-de-documentation" aria-label="Permalink to &quot;2. Publier les sources de documentation&quot;">​</a></h2><p>Après relecture et avec votre compte GitHub autorisé :</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Set-Location</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> C:\\devs\\vite</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">plugin</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">feathersjs</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\scripts\\r17\\certify</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">and</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">stage</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pages</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">windows.ps1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Push</span></span></code></pre></div><p>Le script clone le dépôt GitHub dans un répertoire temporaire indépendant. Il crée une branche de correction dédiée (par défaut <code>docs/vitepress-postcss-isolation-r17-r3-r6</code>), n&#39;ajoute que les sources publiques VitePress et son workflow, puis la pousse. Ouvrez ensuite une pull request ciblant <code>main</code>, vérifiez la liste des fichiers et fusionnez-la.</p><h2 id="_3-activer-github-pages" tabindex="-1">3. Activer GitHub Pages <a class="header-anchor" href="#_3-activer-github-pages" aria-label="Permalink to &quot;3. Activer GitHub Pages&quot;">​</a></h2><ol><li>Dans le dépôt GitHub, ouvrez <strong>Settings → Pages</strong>.</li><li>Sous <strong>Build and deployment → Source</strong>, choisissez <strong>GitHub Actions</strong>.</li><li>Dans <strong>Actions</strong>, vérifiez le workflow <strong>CLI Documentation (VitePress / GitHub Pages)</strong>. En cas de besoin, lancez-le avec <strong>Run workflow</strong> sur <code>main</code>.</li><li>Vérifiez que les étapes build et deploy sont toutes deux vertes, puis ouvrez <code>https://vevedh.github.io/vite-plugin-feathersjs/</code>.</li></ol><p>Le workflow utilise <code>actions/configure-pages</code>, <code>actions/upload-pages-artifact</code> et <code>actions/deploy-pages</code> et ne publie pas de secrets npm. Il est déclenché par les modifications apportées à <code>docs/cli</code> ou au workflow lui-même.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Un build local réussi ou une branche GitHub poussée ne prouvent <strong>pas</strong> que le site est en ligne. Il faut confirmer le résultat du workflow et ouvrir l&#39;URL publique.</p></div><h2 id="_4-si-github-actions-echoue-sur-postcss-nesting" tabindex="-1">4. Si GitHub Actions échoue sur <code>postcss-nesting</code> <a class="header-anchor" href="#_4-si-github-actions-echoue-sur-postcss-nesting" aria-label="Permalink to &quot;4. Si GitHub Actions échoue sur `postcss-nesting`&quot;">​</a></h2><p>La documentation et le plugin historique utilisent des configurations CSS différentes. Sur GitHub, VitePress peut tenter de charger une configuration PostCSS appartenant au <code>package.json</code> de la racine. Le fichier <code>docs/cli/postcss.config.cjs</code> évite cette confusion en donnant à la documentation sa propre configuration, sans plugin externe.</p><p>Ne modifiez pas le <code>package.json</code> du plugin historique et n&#39;installez pas <code>postcss-nesting</code> inutilement pour masquer cette erreur. Relancez la construction dans <strong>Actions</strong>, et confirmez que les deux étapes <code>build</code> et <code>deploy</code> sont réussies.</p>',17)])])}const g=s(n,[["render",o]]);export{h as __pageData,g as default};
